import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Plugin System in Handl","description":"","frontmatter":{"title":"Plugin System in Handl","type":"adr","date":"2026-09-02T00:00:00.000Z","status":"proposed","status_note":"Proposed — the plugin system is a handl module over two Rust layers."},"headers":[],"relativePath":"handl/project/adrs/0050-plugin-system-in-handl.md","filePath":"vendored/handl/project/adrs/0050-plugin-system-in-handl.md"}`),a={name:`handl/project/adrs/0050-plugin-system-in-handl.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0050-plugin-system-in-handl" tabindex="-1">ADR-0050: Plugin System in Handl <a class="header-anchor" href="#adr-0050-plugin-system-in-handl" aria-label="Permalink to “ADR-0050: Plugin System in Handl”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>Two permanent Rust layers; everything above is handl.</strong> The FFI/binding façade and the AST access below it stay Rust; the plugin system is handl.</li><li><strong>The plugin system is a handl module, not a Rust crate</strong> — registry, contribute, dispatch and <code>host.load</code> fixpoint are handl code.</li><li><strong><code>fmt</code> and <code>lint</code> are handl rule acceptors</strong> with one rule file per AST kind.</li><li><strong><code>handle fmt|lint</code> dispatches to the handl tooling kit</strong>, not to Rust implementations.</li><li><strong>Build order</strong>: binding façade → <code>ast.parse</code>/<code>ast.lex</code> access → handl <code>plugin</code> module → handl <code>fmt</code>/<code>lint</code> → per-kind rule files.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>Plugins were Rust crates, so adding a tool or a rule kind meant a rebuild and the plugin system could not be extended by users. A handl registry over a small façade makes plugins data and keeps only the binding/AST layers in Rust.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Keep plugins as Rust crates</strong> — the coupling this removes.</li><li><strong>Put the registry in Rust</strong> — it is pure handl over the façade.</li><li><strong>Bolt fmt/lint onto Rust</strong> — they are handl rule acceptors.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Plugins are handl modules; adding a rule is adding a file.</li><li>The façade is the only Rust growth point.</li><li>The build order is staged and each step is usable.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>crates/plugin-ffi/</code> (façade), <code>crates/plugin-ext-kit/</code> (host.load).</li><li><code>handl-packages/plugin.hnl</code>, <code>fmt.hnl</code>, <code>lint.hnl</code> (handl modules).</li><li>Rule files under the tooling kit.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+The two Rust layers, handl registry, rule acceptors and the build order: +<a href="./../design/0050-plugin-system-in-handl.html"><code>design/0050-plugin-system-in-handl.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};